namespace Ansary;
public sealed class App:Application {
 [STAThread] public static int Main(string[] args){bool smoke=args.Contains("--startup-smoke-test");try{if(smoke)DocumentStore.Verify();var app=new App();var window=new LibraryWindow();bool rendered=false;if(smoke)window.ContentRendered+=(_,_)=>{rendered=true;app.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>app.Shutdown(0)));};int code=app.Run(window);return smoke&&!rendered?1:code;}catch(Exception e){if(smoke){try{File.WriteAllText("startup-smoke-error.txt",e.ToString());}catch{}}else MessageBox.Show("تعذر بدء المكتبة:\n"+e.Message,"الأنصاري");return 1;}}
}
public sealed class SearchHit {
 public required string Path{get;init;}public required int Index{get;init;}public required string Text{get;init;}public required string[] Words{get;init;}public required long Length{get;init;}public required long Ticks{get;init;}public int Offset{get;init;}
}
public sealed class DisplayRow {
 public string Text{get;init;}="";public string[] Words{get;init;}=Array.Empty<string>();public Brush Fill{get;init;}=Brushes.White;public Thickness Indent{get;init;}=new(5);public bool Jump{get;init;}public SearchHit? Hit{get;init;}public int Depth{get;init;}public bool Open{get;set;}=true;public List<DisplayRow> Children{get;}=new();
}
public sealed class HighlightBlock:TextBlock {
 public static readonly DependencyProperty RowProperty=DependencyProperty.Register("Row",typeof(DisplayRow),typeof(HighlightBlock),new PropertyMetadata(null,(d,e)=>((HighlightBlock)d).Paint()));
 public DisplayRow? Row{get=>(DisplayRow?)GetValue(RowProperty);set=>SetValue(RowProperty,value);}
 static readonly Brush[] Colors={Brushes.Yellow,Brushes.LightGreen,Brushes.LightPink,Brushes.LightSkyBlue};Run? anchor;
 public HighlightBlock(){TextWrapping=TextWrapping.Wrap;Padding=new Thickness(6);Loaded+=(_,_)=>Reveal();}
 void Paint(){Inlines.Clear();anchor=null;var row=Row;if(row==null)return;Background=row.Fill;Margin=row.Indent;string text=row.Text;int at=0;while(at<text.Length){int next=-1,which=-1;for(int i=0;i<row.Words.Length;i++){if(row.Words[i].Length==0)continue;int p=text.IndexOf(row.Words[i],at,StringComparison.OrdinalIgnoreCase);if(p>=0&&(next<0||p<next)){next=p;which=i;}}if(next<0){Inlines.Add(new Run(text[at..]));break;}if(next>at)Inlines.Add(new Run(text[at..next]));var run=new Run(text.Substring(next,row.Words[which].Length)){Background=Colors[which%Colors.Length],Foreground=Brushes.Black};Inlines.Add(run);anchor??=run;at=next+row.Words[which].Length;}Reveal();}
 void Reveal(){if(Row?.Jump!=true||!IsLoaded)return;var expected=Row;Dispatcher.BeginInvoke(DispatcherPriority.Loaded,new Action(()=>{if(Row==expected&&IsLoaded)anchor?.BringIntoView();}));}
 public void JumpNow(){Reveal();}
}
public sealed class FastList:ListBox {
 public FastList(){ScrollViewer.SetCanContentScroll(this,true);ScrollViewer.SetHorizontalScrollBarVisibility(this,ScrollBarVisibility.Disabled);VirtualizingPanel.SetIsVirtualizing(this,true);VirtualizingPanel.SetVirtualizationMode(this,VirtualizationMode.Recycling);var panel=new FrameworkElementFactory(typeof(VirtualizingStackPanel));ItemsPanel=new ItemsPanelTemplate(panel);var text=new FrameworkElementFactory(typeof(HighlightBlock));text.SetBinding(HighlightBlock.RowProperty,new Binding());ItemTemplate=new DataTemplate{VisualTree=text};var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Stretch));ItemContainerStyle=style;}
}
public sealed class LibraryWindow:Window {
 readonly TreeView library=new();readonly FastList results=new(),viewer=new(){FontSize=18},viewerResults=new(){MaxHeight=260};readonly Border viewerResultsPanel=new(){Visibility=Visibility.Collapsed,BorderBrush=Brushes.SteelBlue,BorderThickness=new Thickness(1)};
 readonly TextBox query=new(){MinWidth=180},inside=new(){MinWidth=150};readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap};
 readonly WrapPanel tools=new();readonly List<Button> busyButtons=new();readonly List<string> files=new(),errors=new();readonly HashSet<string> selected=new(StringComparer.OrdinalIgnoreCase);readonly DocumentStore cache=new();readonly List<DisplayRow> groups=new();
 readonly string settings=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ElansaryWordLibrary","files.json");
 readonly Button fold;CancellationTokenSource? cancel;int version,phase;SearchHit? current;DisplayRow? activeGroup;DocumentSnapshot? displayed;string[] displayedWords=Array.Empty<string>();ObservableCollection<DisplayRow> paragraphs=new();
 public LibraryWindow(){Title="الأنصاري — مكتبة Word — فهرس دائم ونتائج داخل العارض";Width=1300;Height=850;MinWidth=850;MinHeight=550;FlowDirection=FlowDirection.RightToLeft;var root=new DockPanel{Margin=new Thickness(10)};Content=root;DockPanel.SetDock(tools,Dock.Top);root.Children.Add(tools);DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);
  Add("إضافة مجلد",Folder);Add("إضافة ملفات",()=>{var d=new OpenFileDialog{Filter="Word DOCX|*.docx",Multiselect=true};if(d.ShowDialog(this)==true)Merge(d.FileNames);return Task.CompletedTask;});tools.Children.Add(query);Add("بحث عام",()=>Search(false));Add("إلغاء",()=>{cancel?.Cancel();return Task.CompletedTask;},false);fold=Add("طي النتائج",()=>{Fold();return Task.CompletedTask;},false);Add("طي / فرد ملفات المكتبة",()=>{bool open=!library.Items.OfType<TreeViewItem>().All(n=>n.IsExpanded);foreach(var n in library.Items.OfType<TreeViewItem>())n.IsExpanded=open;return Task.CompletedTask;},false);Add("نسخ النتيجة",()=>{if(results.SelectedItem is DisplayRow{Hit:not null} r)Clipboard.SetText(r.Hit.Path+"\n"+r.Hit.Text);return Task.CompletedTask;},false);Add("تقرير",()=>{MessageBox.Show(string.Join("\n",errors.TakeLast(100)),"تقرير");return Task.CompletedTask;},false);
  var grid=new Grid();root.Children.Add(grid);foreach(double w in new[]{2d,0,3,0,5})grid.ColumnDefinitions.Add(new ColumnDefinition{Width=w==0?new GridLength(5):new GridLength(w,GridUnitType.Star)});grid.Children.Add(library);Grid.SetColumn(results,2);grid.Children.Add(results);var host=new DockPanel();Grid.SetColumn(host,4);grid.Children.Add(host);var bar=new WrapPanel();DockPanel.SetDock(bar,Dock.Top);host.Children.Add(bar);viewerResultsPanel.Child=viewerResults;DockPanel.SetDock(viewerResultsPanel,Dock.Top);host.Children.Add(viewerResultsPanel);host.Children.Add(viewer);bar.Children.Add(new TextBlock{Text="بحث داخل الملف:",Margin=new Thickness(4)});bar.Children.Add(inside);LocalButton(bar,"بحث داخلي",()=>Search(true));LocalButton(bar,"النتائج",()=>{if(current==null){status.Text="افتح ملفًا من نتائج البحث أولًا";return Task.CompletedTask;}viewerResultsPanel.Visibility=viewerResultsPanel.Visibility==Visibility.Visible?Visibility.Collapsed:Visibility.Visible;RefreshViewerResults();return Task.CompletedTask;});LocalButton(bar,"مزامنة",()=>{Sync();return Task.CompletedTask;});LocalButton(bar,"السابق",()=>Navigate(-1));LocalButton(bar,"التالي",()=>Navigate(1));LocalButton(bar,"نسخ الفقرة",()=>{if(viewer.SelectedItem is DisplayRow row)Clipboard.SetText(row.Text);return Task.CompletedTask;});
  foreach(int col in new[]{1,3}){var split=new GridSplitter{Width=5,HorizontalAlignment=HorizontalAlignment.Stretch};Grid.SetColumn(split,col);grid.Children.Add(split);}WireResults(results,true);WireResults(viewerResults,false);
  query.KeyDown+=async(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter)await Search(false);};inside.KeyDown+=async(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter)await Search(true);};Closing+=(_,_)=>{version++;cancel?.Cancel();};
  try{if(File.Exists(settings))files.AddRange((JsonSerializer.Deserialize<string[]>(File.ReadAllText(settings))??Array.Empty<string>()).Where(File.Exists).Distinct(StringComparer.OrdinalIgnoreCase));}catch(Exception e){errors.Add(e.Message);}Rebuild();status.Text="الفهرسة الأولى تستغرق وقتًا؛ البحث اللاحق يستخدم الفهرس المحفوظ. زر النتائج في شريط العارض.";
 }
 void WireResults(FastList list,bool tree){list.PreviewMouseLeftButtonUp+=async(_,e)=>{var row=FindRow(e.OriginalSource as DependencyObject);if(row==null)return;e.Handled=true;list.SelectedItem=row;await Activate(row,tree);};list.KeyDown+=async(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter&&list.SelectedItem is DisplayRow row){e.Handled=true;await Activate(row,tree);}};}
 async Task Activate(DisplayRow row,bool tree){if(row.Hit!=null){activeGroup=groups.FirstOrDefault(g=>Contains(g,row));await Show(row.Hit);}else if(tree){row.Open=!row.Open;RefreshResults();}}
 static DisplayRow? FindRow(DependencyObject? d){while(d!=null){if(d is FrameworkElement f&&f.DataContext is DisplayRow r)return r;d=d is FrameworkContentElement c?c.Parent:VisualTreeHelper.GetParent(d);}return null;}
 static bool Contains(DisplayRow parent,DisplayRow target)=>ReferenceEquals(parent,target)||parent.Children.Any(c=>Contains(c,target));
 Button Add(string label,Func<Task> action,bool busy=true){var b=LocalButton(tools,label,action);if(busy)busyButtons.Add(b);return b;}
 Button LocalButton(Panel panel,string label,Func<Task> action){var b=new Button{Content=label,Margin=new Thickness(3),Padding=new Thickness(6)};panel.Children.Add(b);b.Click+=async(_,_)=>{try{await action();}catch(Exception e){errors.Add(e.ToString());status.Text=e.Message;}};return b;}
 async Task Work(Func<CancellationToken,Task> action){if(cancel!=null){status.Text="انتظر اكتمال العملية أو ألغها أولًا";return;}using var c=new CancellationTokenSource();cancel=c;foreach(var b in busyButtons)b.IsEnabled=false;try{await action(c.Token);}catch(OperationCanceledException){status.Text="تم الإلغاء";}catch(Exception e){errors.Add(e.ToString());status.Text=e.Message;}finally{cancel=null;foreach(var b in busyButtons)b.IsEnabled=true;}}
 async Task Folder(){var d=new OpenFolderDialog{Title="اختر مجلد ملفات DOCX"};if(d.ShowDialog(this)!=true)return;await Work(async t=>{var scan=await Task.Run(()=>Core.Scan(d.FolderName,t),t);errors.AddRange(scan.Errors);Merge(scan.Files);});}
 void Merge(IEnumerable<string> paths){foreach(var p in paths)if(!files.Contains(p,StringComparer.OrdinalIgnoreCase)){files.Add(p);selected.Add(p);}Directory.CreateDirectory(Path.GetDirectoryName(settings)!);File.WriteAllText(settings,JsonSerializer.Serialize(files));Rebuild();}
 void Rebuild(){library.Items.Clear();foreach(var g in files.OrderBy(p=>p).GroupBy(p=>Path.GetDirectoryName(p)??"")){var folder=new TreeViewItem{Header=g.Key,Background=Brushes.Honeydew,IsExpanded=true};library.Items.Add(folder);foreach(var p in g){var box=new CheckBox{Content=Path.GetFileName(p),ToolTip=p,Background=Brushes.LightBlue,IsChecked=selected.Contains(p),Margin=new Thickness(4)};box.Checked+=(_,_)=>selected.Add(p);box.Unchecked+=(_,_)=>selected.Remove(p);folder.Items.Add(box);}}}
 async Task Search(bool local){var words=Core.Terms(local?inside.Text:query.Text);if(words.Length==0){status.Text="اكتب كلمات البحث";return;}if(local&&current==null){status.Text="افتح ملفًا من نتائج البحث أولًا";return;}var scope=local?new[]{current!.Path}:(selected.Count==0?files:files.Where(selected.Contains)).ToArray();if(scope.Length==0){status.Text="أضف ملفات أولًا";return;}await Work(async token=>{var watch=Stopwatch.StartNew();status.Text="جار تحديث الفهرس وجمع النتائج…";var scan=await Task.Run(()=>{var hits=new List<SearchHit>();var failures=new List<string>();foreach(var path in scope){token.ThrowIfCancellationRequested();try{foreach(var h in cache.Search(path,words,token))hits.Add(new SearchHit{Path=h.Path,Index=h.Index,Text=h.Text,Words=words,Length=h.Length,Ticks=h.Ticks,Offset=words.Min(w=>h.Text.IndexOf(w,StringComparison.OrdinalIgnoreCase))});}catch(Exception e) when(e is not OperationCanceledException){failures.Add(path+": "+e.Message);}}return(hits,failures);},token);token.ThrowIfCancellationRequested();errors.AddRange(scan.failures);var group=new DisplayRow{Text=$"{(local?"داخل الملف":"بحث عام")}: {string.Join(" + ",words)} ({scan.hits.Count})",Depth=0,Fill=Brushes.Lavender};foreach(var folder in scan.hits.GroupBy(h=>Path.GetDirectoryName(h.Path)??"")){var f=new DisplayRow{Text=folder.Key,Depth=1,Fill=Brushes.Honeydew,Indent=new Thickness(12,2,0,2)};group.Children.Add(f);foreach(var file in folder.GroupBy(h=>h.Path)){var n=new DisplayRow{Text=$"{Path.GetFileName(file.Key)} ({file.Count()})",Depth=2,Fill=Brushes.LightBlue,Indent=new Thickness(24,2,0,2)};f.Children.Add(n);foreach(var hit in file){string snippet=hit.Text;int start=Math.Max(0,hit.Offset-80);if(snippet.Length>400)snippet=(start>0?"…":"")+snippet.Substring(start,Math.Min(400,snippet.Length-start))+"…";n.Children.Add(new DisplayRow{Text=$"فقرة {hit.Index+1}: {snippet}",Words=words,Hit=hit,Depth=3,Indent=new Thickness(36,2,0,2)});}}}groups.Add(group);if(current==null)activeGroup=group;phase=0;fold.Content="طي النتائج";RefreshResults();RefreshViewerResults();if(local){viewerResultsPanel.Visibility=Visibility.Visible;var first=AllRows(group).FirstOrDefault(r=>r.Hit!=null);if(first?.Hit!=null){activeGroup=group;await Show(first.Hit);}}watch.Stop();status.Text=$"{scan.hits.Count} نتيجة — فهرسة/بحث وتجهيز: {watch.ElapsedMilliseconds} ms — أخطاء: {scan.failures.Count}";});}
 void RefreshResults(){var visible=new List<DisplayRow>();void AddRows(DisplayRow r){visible.Add(r);if(r.Open)foreach(var c in r.Children)AddRows(c);}foreach(var g in groups)AddRows(g);results.ItemsSource=visible;}
 void RefreshViewerResults(){if(current==null){viewerResults.ItemsSource=null;return;}var rows=new List<DisplayRow>();foreach(var group in groups){var matches=AllRows(group).Where(r=>r.Hit!=null&&r.Hit.Path.Equals(current.Path,StringComparison.OrdinalIgnoreCase)).ToList();if(matches.Count==0)continue;rows.Add(new DisplayRow{Text=group.Text,Fill=Brushes.Lavender});rows.AddRange(matches);}viewerResults.ItemsSource=rows;}
 IEnumerable<DisplayRow> AllRows(DisplayRow r){yield return r;foreach(var c in r.Children)foreach(var n in AllRows(c))yield return n;}
 void Fold(){if(groups.Count==0)return;phase=(phase+1)%4;foreach(var r in groups.SelectMany(AllRows)){if(r.Depth==0)r.Open=true;if(r.Depth==1)r.Open=phase!=2;if(r.Depth==2)r.Open=phase==0;}fold.Content=new[]{"طي النتائج","طي الملفات","فرد الملفات","فرد النتائج"}[phase];RefreshResults();}
 DisplayRow ParagraphRow(string text,int index,SearchHit hit)=>new(){Text=text,Words=hit.Words,Jump=index==hit.Index,Fill=index==hit.Index?Brushes.LightCyan:Brushes.White};
 async Task Show(SearchHit hit){int request=++version;var watch=Stopwatch.StartNew();try{var doc=await Task.Run(()=>cache.Get(hit.Path));if(request!=version)return;if(doc.Length!=hit.Length||doc.Ticks!=hit.Ticks||hit.Index>=doc.Paragraphs.Length||doc.Paragraphs[hit.Index]!=hit.Text)throw new IOException("تغيّر الملف؛ أعد البحث لتحديث النتائج");if(!ReferenceEquals(displayed,doc)||!displayedWords.SequenceEqual(hit.Words)){paragraphs=new ObservableCollection<DisplayRow>(doc.Paragraphs.Select((text,index)=>ParagraphRow(text,index,hit)));viewer.ItemsSource=paragraphs;displayed=doc;displayedWords=hit.Words;}else{if(current!=null&&current.Index<paragraphs.Count)paragraphs[current.Index]=ParagraphRow(doc.Paragraphs[current.Index],current.Index,hit);paragraphs[hit.Index]=ParagraphRow(doc.Paragraphs[hit.Index],hit.Index,hit);}current=hit;RefreshViewerResults();viewer.SelectedIndex=hit.Index;viewer.ScrollIntoView(paragraphs[hit.Index]);await Dispatcher.InvokeAsync(()=>{if(request==version){viewer.UpdateLayout();viewer.ScrollIntoView(paragraphs[hit.Index]);if(viewer.ItemContainerGenerator.ContainerFromIndex(hit.Index) is DependencyObject c)FindBlock(c)?.JumpNow();}},DispatcherPriority.Loaded);if(request==version)status.Text=$"{Path.GetFileName(hit.Path)} — فقرة {hit.Index+1} — فتح: {watch.ElapsedMilliseconds} ms";}catch(Exception e){if(request==version){errors.Add(e.ToString());status.Text=e.Message;}}}
 static HighlightBlock? FindBlock(DependencyObject d){if(d is HighlightBlock b)return b;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++){var found=FindBlock(VisualTreeHelper.GetChild(d,i));if(found!=null)return found;}return null;}
 void Sync(){if(current==null){status.Text="افتح نتيجة أولًا";return;}var root=activeGroup;if(root==null)return;var target=AllRows(root).FirstOrDefault(r=>r.Hit is SearchHit h&&h.Path.Equals(current.Path,StringComparison.OrdinalIgnoreCase)&&h.Index==current.Index);if(target==null)return;viewerResultsPanel.Visibility=Visibility.Visible;RefreshViewerResults();viewerResults.SelectedItem=target;viewerResults.ScrollIntoView(target);foreach(var r in AllRows(root))if(Contains(r,target))r.Open=true;RefreshResults();results.SelectedItem=target;results.ScrollIntoView(target);}
 async Task Navigate(int direction){if(current==null||activeGroup==null)return;var hits=AllRows(activeGroup).Where(r=>r.Hit!=null&&r.Hit.Path.Equals(current.Path,StringComparison.OrdinalIgnoreCase)).Select(r=>r.Hit!).ToList();int at=hits.FindIndex(h=>h.Index==current.Index);int next=at+direction;if(at<0||next<0||next>=hits.Count){status.Text="لا توجد نتيجة أخرى في الملف بهذا الاتجاه";return;}await Show(hits[next]);}
}
